const D={up:[0,1],down:[0,-1],left:[-1,0],right:[1,0]};
const Q={up:[-0.70710678,0,0,0.70710678],right:[0,0,-0.70710678,0.70710678]};
const px=(c)=>(c-1)*1.1, pz=(r)=>(1-r)*1.1;
const dist=(s)=>(2-s.c)+(2-s.r);
export function initialState(){return {c:0,r:0,moves:0,hint:false,msg:'Reach the orange goal square.'};}
export function reduce({state,event}){
 if(event.type!=='action')return state;
 const s={...state};const a=event.action;
 const won=dist(s)===0;
 if(a==='hint'){ if(won)return state; s.hint=true; s.msg=s.c<2?'Hint: move Right.':'Hint: move Up.'; return s;}
 const d=D[a]; if(!d)return state;
 if(won){s.msg='You already won. Press Reset to play again.';return s;}
 const c=s.c+d[0], r=s.r+d[1];
 if(c<0||c>2||r<0||r>2){s.msg='That move would leave the board.';return s;}
 s.c=c;s.r=r;s.moves++;s.hint=false;
 if(dist(s)===0){s.msg=s.moves===4?'You reached the goal in 4 moves, the shortest possible route!':'You reached the goal in '+s.moves+' moves. The shortest route is 4.';}
 else s.msg='Moved '+a+'.';
 return s;}
export function evaluate({state}){
 const s=state||initialState();
 const x=px(s.c), z=pz(s.r), d=dist(s);
 const dir=s.c<2?'right':'up';
 return {nodes:{tok:{position:[x,0.35,z]},arr:{visible:s.hint&&d>0,position:[x,0.75,z],quaternion:Q[dir]}},
 readouts:{dist:d,moves:s.moves},
 goal:{status:d===0?'won':'playing',message:s.msg}};}
